using System;using System.IO;using Musikbox;
class Freac57Tests {static void Main(string[] args){var song=MediaMetadata.Read(args[0]);foreach(string format in new[]{"MP3","FLAC","WAV","OGG","M4A","OPUS"}){var options=new AudioOptions{Format=format,Bitrate=192,Quality=4,SampleRate=48000,Channels=1};string root=AudioAdvanced.FreacBatch(new[]{song},Path.GetFullPath(args[1]),Path.GetFullPath(args[2]),"/usr/bin/ffmpeg",options,()=>{},(n,t,s)=>{});string target=Directory.GetFiles(root,"*."+format.ToLowerInvariant())[0];var actual=MediaMetadata.Read(target);if(actual.Duration<2.9)throw new Exception("Leere/zu kurze Ausgabe "+format);Console.WriteLine("PASS fre:ac "+format+" · "+actual.Duration+" s");}Console.WriteLine("BESTANDEN 6 echte fre:ac-Konvertierungen (Linux-Komponenten)");}}
